mapper.insert:
-- -- each format has a component table which they can extend -- CREATE TABLE IF NOT EXISTS ${format}_component ( component_id INT GENERATED BY DEFAULT AS IDENTITY, repository_id INT NOT NULL, namespace VARCHAR NOT NULL, name VARCHAR NOT NULL, kind VARCHAR NOT NULL, version VARCHAR NOT NULL, normalized_version VARCHAR, attributes ${JSON_TYPE} NOT NULL, created TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, last_updated TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, entity_version INT, deleted_on TIMESTAMP WITH TIME ZONE NULL, deleted_by VARCHAR(200) NULL,
CONSTRAINT pk_${format}_component_id PRIMARY KEY (component_id), CONSTRAINT uk_${format}_component_coordinate UNIQUE (repository_id, namespace, name, version),
CONSTRAINT fk_${format}_component_repository FOREIGN KEY (repository_id) REFERENCES ${format}_content_repository (repository_id) );
-- This index was added via an uprade step task, see CoordinateMigrationStep_2_13, hence why this is commented out -- CREATE INDEX IF NOT EXISTS idx_${format}_component_coordinate ON ${format}_component (repository_id, namespace, name, version);

mapper.sql:
SELECT  FROM ${format}_component WHERE 
AND deleted_on IS NULL
 AND component_id > #{continuationToken}
ORDER BY component_id
 LIMIT #{limit};

mapper.select:
SELECT COUNT(*) FROM ${format}_component WHERE repository_id = #{repositoryId}
    AND deleted_on IS NULL
     AND kind = #{kind}
     AND (${filter});

SELECT COUNT(DISTINCT component_id) FROM ${format}_asset
WHERE asset_blob_id IS NOT NULL AND repository_id = #{repositoryId}
AND deleted_on IS NULL
 AND kind = #{kind}
 AND (${filter});

SELECT  FROM ${format}_component WHERE repository_id = #{repositoryId}
    AND deleted_on IS NULL
     AND component_id > #{continuationToken}
     AND kind = #{kind}
     AND (${filter})
ORDER BY component_id LIMIT #{limit};

SELECT  FROM ${format}_component
WHERE repository_id = #{repositoryId}
AND deleted_on IS NULL
AND EXISTS (
  SELECT 1 FROM ${format}_asset a
  WHERE a.component_id = ${format}_component.component_id
  AND a.deleted_on IS NULL
)

  AND component_id > #{continuationToken}

ORDER BY component_id

  LIMIT #{limit}

SELECT  FROM ${format}_component
 WHERE (normalized_version IS NULL
        OR normalized_version = '')
AND deleted_on IS NULL
 AND component_id > #{continuationToken}
 ORDER BY component_id LIMIT #{limit};

SELECT component.component_id, component.repository_id, component.namespace, component.name, component.kind, component.version, component.normalized_version, component.attributes, component.created, component.last_updated, component.entity_version, asset.asset_id, asset.repository_id, asset.path, asset.kind, asset.component_id, asset.asset_blob_id, asset.last_downloaded, asset.attributes, asset.created, asset.last_updated, asset.asset_blob_size FROM ( SELECT FROM ${format}_component WHERE repository_id IN
#{repositoryId}
AND deleted_on IS NULL AND component_id > #{continuationToken} AND kind = #{kind} AND (${filter}) ORDER BY component_id LIMIT #{limit} ) AS component LEFT JOIN ${format}_asset AS asset ON component.component_id = asset.component_id AND asset.deleted_on IS NULL ORDER BY component.component_id

SELECT  FROM ${format}_component
WHERE repository_id IN

  #{repositoryId}

AND deleted_on IS NULL
 AND component_id > #{continuationToken}
ORDER BY component_id LIMIT #{limit};

SELECT EXISTS (
  SELECT 1 FROM ${format}_component WHERE  AND name = #{name}
  AND deleted_on IS NULL
);

SELECT version FROM ${format}_component
WHERE namespace = #{namespace} AND name = #{name}
AND deleted_on IS NULL
AND ;

SELECT DISTINCT namespace, name FROM ${format}_component WHERE repository_id = #{repositoryId}
AND deleted_on IS NULL
 AND CONCAT(namespace, '|', name) > #{continuationToken}
ORDER BY namespace ASC, name ASC
 LIMIT #{limit}

mapper.insert:
MERGE INTO ${format}_component (repository_id, namespace, name, kind, version, normalized_version, attributes
, deleted_on, deleted_by
, entity_version
)
KEY (repository_id, namespace, name, version)
VALUES (#{component.repositoryId}, #{component.namespace}, #{component.name},
#{component.kind}, #{component.version}, #{component.normalizedVersion}, #{component.attributes}
, NULL, NULL
, 1
);

